head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnDisabled]<br/>Column 정보를 사용하여 특정 Column 의 disabled 상태를 설정합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 disabled 상태를 설정할 Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Cell(0, col1) 은 disabled true 설정 (Cell 우선 검증용) / 배경색 회색=disabled"', '', 'label1');

    // 조건 설정 (disabled Cell 을 배경색으로 구분: disabled=회색)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // GridView 단위 disabled 를 false 로 설정 (Column 단위 true/false 동작 관찰용)
    target1.setDisabled("grid", false);

    // Cell(0, col1) 에 disabled true 설정 (Cell 단위가 Column 단위보다 우선 적용되는지 검증용)
    target1.setCellDisabled(0, "col1", true);
}



scwin.btn_setColumnDisabled_onclick = function () {
    let colInfo = par_colInfo.getValue();
    let disabledText = par_disabled.getValue();

    if (disabledText === 'omit') {
        // 파라미터 생략 (기본값 false)
        target1.setColumnDisabled(colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisabled('" + colInfo + "')");
    } else if (disabledText === '') {
        // 빈 문자열 설정 (GridView 의 disabled 상태 적용)
        target1.setColumnDisabled(colInfo, "");
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisabled('" + colInfo + "', '')");
    } else {
        let disabled = disabledText === 'true';
        target1.setColumnDisabled(colInfo, disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisabled('" + colInfo + "', " + disabled + ")");
    }

    // Column 단위 disabled 값 확인
    let colDisabled = target1.getColumnDisabled(colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnDisabled('" + colInfo + "') : " + colDisabled);

    // Row 0 기준 실제 적용된 disabled 값 확인 (GridView/Column/Cell 우선순위 반영)
    let allDisabled = target1.getDisabled("all", 0, colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('all', 0, '" + colInfo + "') : " + allDisabled);
}
